const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanhai = ee.Geometry.Point(119.521, 39.948); // Approximate coordinates for Shanhai (Qinhuangdao)
  const beijing = ee.Geometry.Point(116.4074, 39.9042); // Coordinates for Beijing

  const targetStartDate = '2013-08-05';
  const targetEndDate = '2013-08-12';

  const baselineStartYear = 2000;
  const baselineEndYear = 2012;

  const month = 8; // August
  const dayOfMonthStart = 5;
  const dayOfMonthEnd = 12;

  const scale = 1000; // MODIS LST resolution is 1km.

  // 2. Data Acquisition & Processing Function
  // Function to mask invalid pixels (based on QC_Day flags for LST quality) and convert LST to Celsius
  function maskAndConvertLST(image) {
    const lstDay = image.select('LST_Day_1km');
    const qcDay = image.select('QC_Day');

    // LST_QC bits:
    // 0-1: LST quality (00: Good, 01: Low quality, 10: cloud, 11: cloud)
    // We want good quality (00) and not cloud (not 10 or 11).
    // The MODIS documentation says "00" is good quality, "01" is bad, "10" is average, "11" is bad.
    // However, for MOD11A2, 00 is good, 01 is bad (retrieved <30%), 10 is cloudy, 11 is snow/ice.
    // For this question, we should filter out cloudy pixels and bad quality.
    // So, we want bit 0-1 to be '00'.
    const lstQuality = qcDay.rightShift(0).bitwiseAnd(3); // Extract bits 0-1

    // Mask out pixels where LST quality is not good (0)
    const maskedLST = lstDay.updateMask(lstQuality.eq(0));

    // Convert LST from Kelvin * 0.02 to Celsius
    const lstCelsius = maskedLST.multiply(0.02).subtract(273.15);

    return image.addBands(lstCelsius.rename('LST_Celsius'));
  }

  // Function to get mean LST for a given geometry and date range
  async function getMeanLST(geometry, start, end, name) {
    let collection = ee.ImageCollection('MODIS/006/MOD11A2')
      .filterBounds(geometry)
      .filterDate(start, end)
      .map(maskAndConvertLST)
      .select('LST_Celsius');

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${name} between ${start} and ${end}.`);
      return { value: null, pixels: 0, size: 0 };
    }

    const meanLSTImage = collection.mean();
    const countPixels = collection.mosaic().select('LST_Celsius').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });
    const pixelCount = await countPixels.get('LST_Celsius').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels for ${name} between ${start} and ${end} after masking.`);
      return { value: null, pixels: 0, size: collectionSize };
    }

    const meanLST = await meanLSTImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Celsius').getInfo();

    console.log(`${name} Images: ${collectionSize} (Val: ${meanLST !== null ? meanLST.toFixed(2) : 'N/A'}°C, Pixels: ${pixelCount})`);
    return { value: meanLST, pixels: pixelCount, size: collectionSize };
  }

  // 3. Calculate Baseline LST for Shanhai and Beijing
  let shanhaiBaselineLSTs = [];
  let beijingBaselineLSTs = [];
  let totalBaselineImages_shanhai = 0;
  let totalBaselineImages_beijing = 0;

  for (let year = baselineStartYear; year <= baselineEndYear; year++) {
    const baselinePeriodStart = ee.Date.fromYMD(year, month, dayOfMonthStart);
    const baselinePeriodEnd = ee.Date.fromYMD(year, month, dayOfMonthEnd);

    const shanhaiCol = ee.ImageCollection('MODIS/006/MOD11A2')
      .filterBounds(shanhai)
      .filterDate(baselinePeriodStart, baselinePeriodEnd)
      .map(maskAndConvertLST)
      .select('LST_Celsius');

    const shanhaiYearMean = await shanhaiCol.mean().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: shanhai,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Celsius').getInfo();

    if (shanhaiYearMean !== null) {
      shanhaiBaselineLSTs.push(shanhaiYearMean);
    }
    totalBaselineImages_shanhai += await shanhaiCol.size().getInfo();

    const beijingCol = ee.ImageCollection('MODIS/006/MOD11A2')
      .filterBounds(beijing)
      .filterDate(baselinePeriodStart, baselinePeriodEnd)
      .map(maskAndConvertLST)
      .select('LST_Celsius');

    const beijingYearMean = await beijingCol.mean().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: beijing,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Celsius').getInfo();

    if (beijingYearMean !== null) {
      beijingBaselineLSTs.push(beijingYearMean);
    }
    totalBaselineImages_beijing += await beijingCol.size().getInfo();
  }

  if (shanhaiBaselineLSTs.length === 0) {
    console.log("No valid baseline LST data for Shanhai (2000-2012).");
    console.log("C1");
    return;
  }
  if (beijingBaselineLSTs.length === 0) {
    console.log("No valid baseline LST data for Beijing (2000-2012).");
    console.log("C1");
    return;
  }

  const meanShanhaiBaseline = shanhaiBaselineLSTs.reduce((a, b) => a + b, 0) / shanhaiBaselineLSTs.length;
  const meanBeijingBaseline = beijingBaselineLSTs.reduce((a, b) => a + b, 0) / beijingBaselineLSTs.length;

  console.log(`Shanhai Baseline (${baselineStartYear}-${baselineEndYear}) LST: ${meanShanhaiBaseline.toFixed(2)}°C (Total images: ${totalBaselineImages_shanhai})`);
  console.log(`Beijing Baseline (${baselineStartYear}-${baselineEndYear}) LST: ${meanBeijingBaseline.toFixed(2)}°C (Total images: ${totalBaselineImages_beijing})`);

  // 4. Calculate Target Week LST for Shanhai and Beijing
  const shanhaiTarget = await getMeanLST(shanhai, targetStartDate, targetEndDate, 'Shanhai 2013');
  const beijingTarget = await getMeanLST(beijing, targetStartDate, targetEndDate, 'Beijing 2013');

  if (shanhaiTarget.size === 0 || beijingTarget.size === 0) {
    console.log("C1");
    return;
  }
  if (shanhaiTarget.pixels === 0 || beijingTarget.pixels === 0) {
    console.log("C2");
    return;
  }
  if (shanhaiTarget.value === null || beijingTarget.value === null || isNaN(meanShanhaiBaseline) || isNaN(meanBeijingBaseline)) {
    console.log("C3");
    return;
  }

  // 5. Calculate LST Anomaly
  const shanhaiAnomaly = shanhaiTarget.value - meanShanhaiBaseline;
  const beijingAnomaly = beijingTarget.value - meanBeijingBaseline;

  console.log(`Shanhai Anomaly: ${shanhaiAnomaly.toFixed(2)}°C`);
  console.log(`Beijing Anomaly: ${beijingAnomaly.toFixed(2)}°C`);

  // 6. Compare Anomalies and provide final answer
  if (shanhaiAnomaly > beijingAnomaly) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
